a=ResearchAuthor('ai-7/27')
for old,new in [('Two 45-minute sessions.','Use the three-session teaching cycle above, with extra time as needed.'),('passes9','passes 9'),('and5','and 5'),('versus50','versus 50'),('gap40','gap 40'),('conditionA','condition A'),('conditionB','condition B')]:
 if old in str(a.w):a.replace_text(old,new)
present_case(a,
 headline='Keep condition-specific results visible when checking robustness',
 purpose='Compare frozen procedures across declared conditions without replacing slices with one pooled score.',
 intro='A method can do well in one setting and poorly in another. Robustness checks ask how the frozen procedure behaves across relevant declared conditions, using aligned scoring, eligibility and baselines. Report each slice and its denominator before any overall total. A difference identifies a pattern to investigate, not its cause. A pooled score can conceal a weak condition, especially when the mix of cases differs from the intended use.',
 contract=[['Robustness item','Complete supplied exercise contract'],['Main condition counts','Current sources: 9/10 pass; outdated sources: 5/10'],['Main interpretation','Condition-associated descriptive difference; no causal mechanism identified'],['Separate picture','Frozen classifier and rubric unchanged; indoor 7/8 correct, outdoor 3/8'],['Picture pooled count','Ten correct among sixteen cases'],['Needed for a controlled follow-up','Aligned baseline, scoring and eligibility; recorded case/condition changes'],['Not supplied','Per-case outputs, matched-case transition identities, stable population rates or significance'],['Scope','Fictional supplied summaries; no new model run or data collection']],
 ledger=[['Main quantity','Current sources','Outdated sources'],['Passes / evaluated','9/10','5/10'],['Observed rate','90%','50%'],['Current minus outdated','40 percentage points','Lower quality associated with this condition here'],['Mechanism','Not identified','Inspect source validity and procedure traces'],['Generalization','Only supplied cases','No universal causal or robustness conclusion']],
 picture='The separate frozen-classifier picture has seven correct of eight indoor cases, or 87.5%, and three correct of eight shaded outdoor cases, or 37.5%. The descriptive slice gap is fifty percentage points. Combined correctness is ten of sixteen, or 62.5%. Reporting only that pooled score hides the weaker outdoor slice and is not a result for either setting alone. Eight cases per slice do not establish stable population rates or the reason for the difference. Keep the model and rubric frozen in the stated comparison, but do not mistake that exercise assumption for code-verified controls or full sampling evidence.',
 picture_table=[['Separate picture slice','Correct / total','Observed rate'],['Indoor','7/8','87.5%'],['Outdoor shade','3/8','37.5%'],['Pooled','10/16','62.5%'],['Indoor minus outdoor','Different supplied slices','50 percentage points'],['Hidden by pooled-only report','Outdoor weakness','No separate outdoor rate visible'],['Why rates differ','Not supplied','No causal or significance claim']],
 probes=[['Robustness audit','Checked interpretation'],['Overall score looks acceptable','A weak relevant condition can still be hidden'],['Same frozen model and rubric','Useful declared controls, not proof all case properties align'],['Outdoor score lower','Descriptive pattern, not a root-cause diagnosis'],['New condition tested','Extends evidence to that condition only'],['One candidate improves one slice','Check whether another slice worsens'],['Two conditions pooled','Their observed weights may differ from intended use'],['Only aggregate counts supplied','Cannot reconstruct individual paired flips'],['No statistical analysis supplied','Do not label slice gaps statistically established']],
 investigation='Predict the main 90% and 50% rates and forty-point gap. The complete code separately computes the picture’s 87.5%, 37.5% and pooled 62.5%, making the different denominators visible. It summarizes supplied counts only; it does not run a classifier or verify the declared controls. Save the slice results alongside the pooled value and propose a follow-up that holds the baseline, metric and eligibility aligned. Leave causal explanations and population rates unresolved. Keep the independent baseline/candidate comparison for the first individual attempt.',
 teacher_key='Main current 9/10 = 90%, outdated 5/10 = 50%, gap forty percentage points. Do not claim the source condition alone caused the difference. Picture indoor 7/8 = 87.5%, outdoor 3/8 = 37.5%, gap fifty points; pooled 10/16 = 62.5% hides the weaker slice. Independent condition A baseline 6/8 = 75% and candidate 7/8 = 87.5% gives +12.5 points; condition B baseline 5/8 = 62.5% and candidate 4/8 = 50% gives −12.5 points. Both pooled totals are 11/16, so the tie hides opposite condition effects. Per-case flip identities are not supplied despite paired-rate wording. No significance, universal advantage or causal attribution follows.',
 reference='Robustness checks compare a frozen procedure under declared varied conditions. Keep baseline, scoring and eligibility aligned and report slices separately. Main current-source pass rate is 9/10 = 90%, outdated-source 5/10 = 50%, a forty-percentage-point descriptive gap. This association does not identify a cause. Separate frozen-classifier picture has indoor 7/8 = 87.5% and outdoor 3/8 = 37.5%, gap fifty points. Pooling yields 10/16 = 62.5%; reporting only that value hides outdoor weakness. The observed case mix need not match future use. Eight cases per slice do not establish stable population rates, significance or universal robustness. Aggregate counts cannot reconstruct individual paired transitions. New conditions extend the evidence only to their tested scope. The code calculates supplied summaries, without running a model, collecting cases or verifying actual controls.',
 independent='Compare baseline and candidate within each condition, preserving opposite changes and the limits of aggregate counts.',
 image={'type':'image','src':'/api/resource/ai-7-27-slice-rates','alt':'Frozen classifier is correct on seven of eight indoor cases, eighty-seven point five percent, and three of eight outdoor cases, thirty-seven point five percent. Pooled ten of sixteen is sixty-two point five percent and hides a fifty-percentage-point slice gap.','caption':'Supplied descriptive slice rates, with an axis from zero to one hundred percent. These small slices do not establish cause or stable population performance.'},
 code={'type':'code','language':'python','title':'Complete declared-condition slice and pooled-rate audit','text':Path(__file__).with_name('ai7_week27_condition_audit.py').read_text()})
